inline const wchar_t* Direction(std::wstring_view name) noexcept {
    if (name == L"ServerToNpc") {
        return L"L2Server -> L2NPC";
    }
    if (name == L"NpcToServer") {
        return L"L2NPC -> L2Server";
    }
    return nullptr;
}

inline const wchar_t* PacketName(std::wstring_view direction, bool extended, int opcode) noexcept {
    if (opcode < 0) {
        return nullptr;
    }
    const auto index = static_cast<std::size_t>(opcode);
    if (direction == L"ServerToNpc" && !extended && index < kServerToNpc.size()) {
        return kServerToNpc[index];
    }
    if (direction == L"NpcToServer") {
        if (extended && index < kNpcToServerExtended.size()) {
            return kNpcToServerExtended[index];
        }
        if (!extended && index < kNpcToServer.size()) {
            return kNpcToServer[index];
        }
    }
    return nullptr;
}

